215: static int ak_isp_open(struct inode *inode,struct file *file)
216: {
217:  struct miscdevice *misc=file->private_data;
218:  struct ak_isp *isp=container_of(misc,struct ak_isp,misc);
219:  struct ak_isp_file *fc;int ret=0;
220:  (void)inode;
221:  /* Linux6.18 misc_open holds misc_mtx through this callback; registration ref
222:   * is retained until matching misc_deregister returns. First get is safe. */
223:  kref_get(&isp->references);mutex_lock(&isp->lock);
224:  if(!isp->ready || isp->disconnected || isp->quarantined){ret=isp->quarantined?-EIO:-ENODEV;file->private_data=NULL;goto out;}
225:  fc=ak_isp_file_alloc(isp);if(IS_ERR(fc)){ret=PTR_ERR(fc);file->private_data=NULL;goto out;}
226:  file->private_data=fc;
227: out:
228:  mutex_unlock(&isp->lock);ak_isp_bundle_put(isp);return ret;
229: }
