236: {
237:  struct ak_isp *isp=fc->isp;struct ak_isp_user_copy a={arg};
238:  struct qc_retirement_uaccess u={ak_isp_receipt_from,ak_isp_receipt_to,&a};int ret;
239:  if(cmd==QC_ISP_RECEIPT_ARM && (isp->disconnected || isp->quarantined))return isp->disconnected?-ENODEV:-EIO;
