1492: static void ak_isp_bundle_release(struct kref *ref)
1493: {
1494:  struct ak_isp *isp=container_of(ref,struct ak_isp,references);
1495:  struct device *dev=isp->dev;
1496:  if(WARN_ON(!isp->disconnected || !isp->dma_retired || isp->session || isp->receipt_source.hold ||
1497:             isp->receipt_source.open_files || isp->quarantined))return;
1498:  if(isp->irq_registered){synchronize_irq(isp->irq);free_irq(isp->irq,isp);isp->irq_registered=false;}
1499:  ak_isp_ring_release_buffers(isp); /* ring[0] aliases frame; helper never frees it */
1500:  if(isp->reference)qc_isp_free(isp,REF_ALLOC,isp->reference,isp->reference_dma);
1501:  if(isp->frame)qc_isp_free(isp,FRAME_ALLOC,isp->frame,isp->frame_dma);
1502:  if(isp->table)qc_isp_free(isp,TABLE_ALLOC,isp->table,isp->table_dma);
1503:  if(isp->base)iounmap(isp->base);
1504:  if(isp->region_owned)release_mem_region(isp->region_start,isp->region_bytes);
1505:  of_node_put(isp->sys_np);
1506:  mutex_lock(&ak_isp_registry_lock);WARN_ON(ak_isp_live!=isp);ak_isp_live=NULL;mutex_unlock(&ak_isp_registry_lock);
1507:  kfree(isp);put_device(dev);
1508: }
