1580: static void ak_isp_remove(struct platform_device *pdev)
1581: {
1582:  struct ak_isp *isp=platform_get_drvdata(pdev);
1583:  if(!isp)return;
1584:  kref_get(&isp->references);mutex_lock(&isp->lock);isp->disconnected=true;mutex_unlock(&isp->lock);
1585:  /* Removal of the sysfs group drains active callbacks; do not hold source lock.
1586:   * misc_deregister serializes its first-kref/open handoff via misc_mtx. */
1587:  if(isp->attrs_registered){sysfs_remove_group(&pdev->dev.kobj,&ak_isp_attr_group);isp->attrs_registered=false;}
1588:  if(isp->misc_registered){misc_deregister(&isp->misc);isp->misc_registered=false;}
1589:  mutex_lock(&isp->lock);
1590:  if(!isp->dma_retired && !isp->quarantined){isp->stop_reason=QC_STOP_CLOSE;ak_isp_lifecycle_stop(isp,false);}
1591:  qc_stage_owner(&isp->telemetry,!!isp->stream_owner,0);
1592:  if(isp->irq_registered)synchronize_irq(isp->irq);
1593:  /* No worker/timer exists in frozen72; IRQ synchronization plus source mutex
1594:   * drains every actual async producer. No invented workqueue success callback. */
1595:  if(!isp->dma_retired)ak_isp_quarantine(isp,isp->quarantine_result);
1596:  if(isp->session && !isp->session->receipt.open && isp->dma_retired)
1597:   ak_isp_consume_retired(isp,isp->session);
1598:  mutex_unlock(&isp->lock);platform_set_drvdata(pdev,NULL);
1599:  ak_isp_bundle_put(isp); /* registration */
1600:  ak_isp_bundle_put(isp); /* remove operation */
1601:  /* Failed reset retains one registry bundle + its own context/IRQ/MMIO/DMA.
1602:   * There is deliberately no unsafe automatic recovery access after remove. */
1603: }
