429: static int encoder_release(struct inode *inode,struct file *file)
430: {
431:  mutex_lock(&enc.lock);
432:  if(enc.h264_owner==file){
433:   qc_stage_begin(qc_codec_trace(),QC_STAGE_END,ktime_get_ns());
434:   enc.h264_owner=NULL;
435:   qc_stage_owner(qc_codec_trace(),!!enc.h264_owner,0);
436:   qc_stage_end(qc_codec_trace(),0,0,ktime_get_ns());
437:  }
438:  /* File pointer must not survive release. Fault identity is a non-reused
439:   * numeric session, independent of this allocation and retained forever.
440:   * Synchronous jobs retire before returning or quarantine; no close retry.
441:   */
442:  kfree(file->private_data);file->private_data=NULL;
443:  mutex_unlock(&enc.lock);return 0;
444: }
445: static int encoder_open(struct inode *inode,struct file *file)
446: {
447:  struct qc_encoder_session *session;
448:  int result=0;
449:  session=kzalloc(sizeof(*session),GFP_KERNEL);if(!session)return -ENOMEM;
450:  mutex_lock(&enc.lock);
451:  if(enc.quarantined)result=-EIO;
452:  else if(enc.guard_poisoned)result=-EOVERFLOW;
453:  else if(enc.session_sequence==~(u64)0)result=-EOVERFLOW;
454:  else{session->identity=++enc.session_sequence;file->private_data=session;}
455:  mutex_unlock(&enc.lock);
456:  if(result)kfree(session);
457:  return result;

478: static int __init encoder_init(void)
479: {
