486:  enc.regs=ioremap(CODEC_BASE,CODEC_BYTES);if(!enc.regs){result=-ENOMEM;goto release;}
487:  enc.pdev=platform_device_register_simple("qc07f-hwenc-dma",-1,NULL,0);if(IS_ERR(enc.pdev)){result=PTR_ERR(enc.pdev);goto unmap;}
488:  telemetry=kzalloc(sizeof(*telemetry),GFP_KERNEL);
489:  if(!telemetry){result=-ENOMEM;goto device;}
490:  qc_stage_codec_coverage(telemetry);
491:  dev_set_drvdata(&enc.pdev->dev,telemetry);
