42: int qc_retirement_ioctl(struct qc_retirement_file *f,unsigned long cmd,const struct qc_retirement_uaccess *u)
43: {
44:  struct qc_capture_receipt q;
45:  if(!valid(f)||!u||!u->from_user||!u->to_user)return -EINVAL;
46:  if(!f->open)return -EBADF;
47:  if(cmd!=QC_ISP_RECEIPT_BIND&&cmd!=QC_ISP_RECEIPT_ARM&&cmd!=QC_ISP_RECEIPT_QUERY&&cmd!=QC_ISP_RECEIPT_ACK)return -ENOTTY;
48:  if(u->from_user(u->context,&q))return -EFAULT;
49:  if(!input_clean(&q))return -EINVAL;
50:  if(cmd==QC_ISP_RECEIPT_BIND){
51:   if(q.source_instance||q.file_instance||q.generation)return -EINVAL;
52:   reply(f,&q);return u->to_user(u->context,&q)?-EFAULT:0;
53:  }
54:  if(!binding(f,&q))return -ESTALE;
55:  if(cmd==QC_ISP_RECEIPT_ARM){
56:   if(q.generation)return -EINVAL;
57:   if(f->state!=QC_RECEIPT_NONE||f->source->hold)return -EBUSY;
58:   if(f->source->next_generation==QC_U64_MAX)return -EOVERFLOW;
59:   __u64 generation=++f->source->next_generation; /* never recycle even on EFAULT */
60:    reply(f,&q);q.generation=generation;q.state=QC_RECEIPT_ARMED;
61:    q.reason=QC_STOP_NONE;q.stop_result=0;q.stopped_ns=0;
62:   /* Publish generation BEFORE any hardware begin. A bad reply must not reserve
63:    * the owner or run/reset hardware. Begin subsequently needs the committed ARM.
64:    */
65:   if(u->to_user(u->context,&q))return -EFAULT;
66:    f->generation=generation;f->state=QC_RECEIPT_ARMED;
67:    f->reason=QC_STOP_NONE;f->stop_result=0;f->stopped_ns=0;
68:    f->source->hold=f;return 0;
69:  }
70:  if(!held(f)||q.generation!=f->generation)return -ESTALE;
71:  if(cmd==QC_ISP_RECEIPT_QUERY){
72:   reply(f,&q);return u->to_user(u->context,&q)?-EFAULT:0; /* NEVER resets/consumes */
73:  }
74:  if(f->state!=QC_RECEIPT_RETIRED||f->stop_result)return -EBUSY;
75:  /* ACK only consumes a proven receipt. Copy-from and validation precede commit;
76:   * no copy-to or hardware side effect. A successor invalidates this old key.
77:   */
78:  f->source->hold=NULL;f->generation=0;f->state=QC_RECEIPT_NONE;
79:  f->reason=QC_STOP_NONE;f->stop_result=0;f->stopped_ns=0;return 0;

