647: 		return cpu_addr;
648: 	}
649: 
650: 	/* let the implementation decide on the zone to allocate from: */
651: 	flag &= ~(__GFP_DMA | __GFP_DMA32 | __GFP_HIGHMEM);
652: 
653: 	if (dma_alloc_direct(dev, ops)) {
654: 		cpu_addr = dma_direct_alloc(dev, size, dma_handle, flag, attrs);
655: 	} else if (use_dma_iommu(dev)) {
656: 		cpu_addr = iommu_dma_alloc(dev, size, dma_handle, flag, attrs);
657: 	} else if (ops->alloc) {
658: 		cpu_addr = ops->alloc(dev, size, dma_handle, flag, attrs);
659: 	} else {
660: 		trace_dma_alloc(dev, NULL, 0, size, DMA_BIDIRECTIONAL, flag,
661: 				attrs);
662: 		return NULL;
663: 	}
664: 
665: 	trace_dma_alloc(dev, cpu_addr, *dma_handle, size, DMA_BIDIRECTIONAL,
666: 			flag, attrs);
667: 	debug_dma_alloc_coherent(dev, size, *dma_handle, cpu_addr, attrs);
668: 	return cpu_addr;

205: 	bool remap = false, set_uncached = false;
206: 	struct page *page;
207: 	void *ret;
208: 
209: 	size = PAGE_ALIGN(size);
210: 	if (attrs & DMA_ATTR_NO_WARN)
211: 		gfp |= __GFP_NOWARN;
212: 
213: 	if ((attrs & DMA_ATTR_NO_KERNEL_MAPPING) &&
214: 	    !force_dma_unencrypted(dev) && !is_swiotlb_for_alloc(dev))
215: 		return dma_direct_alloc_no_mapping(dev, size, dma_handle, gfp);
216: 
217: 	if (!dev_is_dma_coherent(dev)) {
218: 		if (IS_ENABLED(CONFIG_ARCH_HAS_DMA_ALLOC) &&
219: 		    !is_swiotlb_for_alloc(dev))
220: 			return arch_dma_alloc(dev, size, dma_handle, gfp,
221: 					      attrs);

