89: 						phys_addr_t paddr)
90: {
91: 	return dma_addr_unencrypted(__phys_to_dma(dev, paddr));
92: }
93: /*
94:  * If memory encryption is supported, phys_to_dma will set the memory encryption
95:  * bit in the DMA address, and dma_to_phys will clear it.
96:  * phys_to_dma_unencrypted is for use on special unencrypted memory like swiotlb
97:  * buffers.
98:  */
99: static inline dma_addr_t phys_to_dma(struct device *dev, phys_addr_t paddr)
100: {
101: 	return dma_addr_encrypted(__phys_to_dma(dev, paddr));
102: }
103: 
104: static inline phys_addr_t dma_to_phys(struct device *dev, dma_addr_t dma_addr)
105: {
106: 	phys_addr_t paddr;
107: 
108: 	dma_addr = dma_addr_canonical(dma_addr);
109: 	if (dev->dma_range_map)
110: 		paddr = translate_dma_to_phys(dev, dma_addr);
111: 	else
112: 		paddr = dma_addr;
113: 
114: 	return paddr;
115: }

782: static int cma_range_alloc(struct cma *cma, struct cma_memrange *cmr,
783: 				unsigned long count, unsigned int align,
784: 				struct page **pagep, gfp_t gfp)
785: {
786: 	unsigned long bitmap_maxno, bitmap_no, bitmap_count;
787: 	unsigned long start, pfn, mask, offset;
788: 	int ret = -EBUSY;
789: 	struct page *page = NULL;
790: 
791: 	mask = cma_bitmap_aligned_mask(cma, align);
792: 	offset = cma_bitmap_aligned_offset(cma, cmr, align);
793: 	bitmap_maxno = cma_bitmap_maxno(cma, cmr);
794: 	bitmap_count = cma_bitmap_pages_to_bits(cma, count);
795: 
796: 	if (bitmap_count > bitmap_maxno)
797: 		goto out;
798: 
799: 	for (start = 0; ; start = bitmap_no + mask + 1) {
800: 		spin_lock_irq(&cma->lock);
801: 		/*
802: 		 * If the request is larger than the available number
803: 		 * of pages, stop right away.
804: 		 */
805: 		if (count > cma->available_count) {
806: 			spin_unlock_irq(&cma->lock);
807: 			break;
808: 		}
809: 		bitmap_no = bitmap_find_next_zero_area_off(cmr->bitmap,
810: 				bitmap_maxno, start, bitmap_count, mask,
811: 				offset);
812: 		if (bitmap_no >= bitmap_maxno) {
813: 			spin_unlock_irq(&cma->lock);
814: 			break;
815: 		}
816: 
817: 		pfn = cmr->base_pfn + (bitmap_no << cma->order_per_bit);
818: 		page = pfn_to_page(pfn);
819: 
820: 		/*
821: 		 * Do not hand out page ranges that are not contiguous, so
822: 		 * callers can just iterate the pages without having to worry
823: 		 * about these corner cases.
824: 		 */
825: 		if (!page_range_contiguous(page, count)) {
826: 			spin_unlock_irq(&cma->lock);
827: 			pr_warn_ratelimited("%s: %s: skipping incompatible area [0x%lx-0x%lx]",
828: 					    __func__, cma->name, pfn, pfn + count - 1);
829: 			continue;
830: 		}
831: 
832: 		bitmap_set(cmr->bitmap, bitmap_no, bitmap_count);
833: 		cma->available_count -= count;
834: 		/*
835: 		 * It's safe to drop the lock here. We've marked this region for
836: 		 * our exclusive use. If the migration fails we will take the
837: 		 * lock again and unmark it.
838: 		 */
839: 		spin_unlock_irq(&cma->lock);
840: 
841: 		mutex_lock(&cma->alloc_mutex);
842: 		ret = alloc_contig_range(pfn, pfn + count, ACR_FLAGS_CMA, gfp);
843: 		mutex_unlock(&cma->alloc_mutex);
844: 		if (!ret)
845: 			break;
846: 
847: 		cma_clear_bitmap(cma, cmr, pfn, count);
848: 		if (ret != -EBUSY)
849: 			break;
850: 
851: 		pr_debug("%s(): memory range at pfn 0x%lx %p is busy, retrying\n",
852: 			 __func__, pfn, page);
853: 
854: 		trace_cma_alloc_busy_retry(cma->name, pfn, page, count, align);
855: 	}
856: out:
857: 	if (!ret)
858: 		*pagep = page;
859: 	return ret;

