114: int nh_memory_evaluate(const struct nh_memory_ledger *l,const struct nh_memory_values *a,
115:  const struct nh_memory_values *b,const struct nh_memory_zones *z,uint64_t begin,uint64_t end,
116:  enum nh_memory_stage stage,struct nh_memory_observation *out)
117: {
118:  if(!l||!a||!b||!z||!out||!l->initialized||l->cpu_paid_kib>l->cpu_capacity_kib)return NH_MEM_FORMAT;
119:  struct nh_memory_observation o={.begin_ns=begin,.end_ns=end,.stage=stage,.reason=NH_MEM_OK};
120:  if(begin==UINT64_MAX||end==UINT64_MAX||end<begin)o.reason=NH_MEM_CLOCK;
121:  else if(end-begin>NH_MEMORY_MAX_SAMPLE_NS)o.reason=NH_MEM_STALE;
122:  o.available=a->available<b->available?a->available:b->available;
123:  uint64_t free=a->free<b->free?a->free:b->free,cma=a->cma_free>b->cma_free?a->cma_free:b->cma_free;
124:  o.watermark_kib=z->watermark_kib;o.cpu_debt=l->cpu_capacity_kib-l->cpu_paid_kib;o.dma_debt=l->codec_paid?0:NH_MEMORY_CODEC_KIB;
125:  o.required_available=o.cpu_debt+o.dma_debt+NH_MEMORY_OVERHEAD_KIB+NH_MEMORY_RESERVE_KIB;
126:  /* Full unpaid CPU may land in Normal. Resident owned pages may have borrowed
127:   * CMA and can be evacuated by initial codec allocation. Without qualified
128:   * placement proof, ALL current occupied CMA is potentially migratable, capped
129:   * by the still-unpaid codec ranges. This includes own loans without double
130:   * adding them; known-nonmovable ISP is NOT subtracted on a placement guess. */
131:  uint64_t minimum_cma=a->cma_free<b->cma_free?a->cma_free:b->cma_free;
132:  if(z->normal.free_cma*4<minimum_cma)minimum_cma=z->normal.free_cma*4;
133:  uint64_t occupied=a->cma_total>=minimum_cma?a->cma_total-minimum_cma:UINT64_MAX;
134:  o.migration_future_kib=l->codec_paid?0:(occupied<o.dma_debt?occupied:o.dma_debt);
135:  o.required_noncma=o.cpu_debt+o.migration_future_kib+NH_MEMORY_OVERHEAD_KIB+NH_MEMORY_RESERVE_KIB;
136:  uint64_t zone_noncma=(z->normal.free-z->normal.free_cma)*4;
137:  if(free>=cma&&zone_noncma<free-cma)free=zone_noncma+cma;
138:  if(free<cma||free-cma<z->watermark_kib){o.noncma_free=0;if(!o.reason)o.reason=NH_MEM_LOW_NONCMA;}
139:  else o.noncma_free=free-cma-z->watermark_kib;
140:  if(!o.reason&&o.available<o.required_available)o.reason=NH_MEM_LOW_AVAILABLE;
141:  if(!o.reason&&o.noncma_free<o.required_noncma)o.reason=NH_MEM_LOW_NONCMA;
142:  *out=o;return (int)o.reason;
143: }

24: int nh_memory_runtime_init(struct nh_memory_runtime *r,uint64_t start,
25:  uint64_t (*now)(void *),int (*cancelled)(void *),void *context,unsigned raw_reuse)
26: {
27:  uint64_t capacity,nonmovable;if(!r||!now||!cancelled||start==UINT64_MAX||nh_memory_own_layout(&capacity,&nonmovable,raw_reuse))return NH_MEM_LAYOUT;
28:  memset(r,0,sizeof(*r));if(nh_memory_init_mode(&r->ledger,capacity,nonmovable,raw_reuse))return NH_MEM_LAYOUT;
29:  r->session_start=start;r->now=now;r->cancelled=cancelled;r->context=context;return NH_MEM_OK;
