31: int nh_memory_runtime_gate(struct nh_memory_runtime *r,enum nh_memory_stage stage,uint64_t unit_start)
32: {
33:  if(!r||!r->ledger.initialized||r->count>=64)return NH_MEM_FORMAT;
34:  struct nh_memory_observation o={.stage=stage};struct nh_memory_values first,last;struct nh_memory_zones zones;
35:  uint64_t now;size_t bytes;int reason=checked(r,unit_start,&o.begin_ns);if(reason)goto failed;
36:  if(nh_memory_read_fixed(0,r->meminfo,sizeof(r->meminfo),&bytes)){reason=NH_MEM_IO;goto failed;}
37:  if(nh_memory_parse_meminfo(r->meminfo,bytes,&first)){reason=NH_MEM_FORMAT;goto failed;}
38:  reason=checked(r,unit_start,&now);if(reason)goto failed;
39:  if(now<o.begin_ns||now-o.begin_ns>NH_MEMORY_MAX_SAMPLE_NS){reason=now<o.begin_ns?NH_MEM_CLOCK:NH_MEM_STALE;goto failed;}
40:  if(nh_memory_read_fixed(1,r->zoneinfo,sizeof(r->zoneinfo),&bytes)){reason=NH_MEM_IO;goto failed;}
41:  if(nh_memory_parse_zoneinfo(r->zoneinfo,bytes,&zones)){reason=NH_MEM_LAYOUT;goto failed;}
42:  reason=checked(r,unit_start,&now);if(reason)goto failed;
43:  if(now<o.begin_ns||now-o.begin_ns>NH_MEMORY_MAX_SAMPLE_NS){reason=now<o.begin_ns?NH_MEM_CLOCK:NH_MEM_STALE;goto failed;}
44:  if(nh_memory_read_fixed(0,r->meminfo,sizeof(r->meminfo),&bytes)){reason=NH_MEM_IO;goto failed;}
45:  if(nh_memory_parse_meminfo(r->meminfo,bytes,&last)){reason=NH_MEM_FORMAT;goto failed;}
46:  reason=checked(r,unit_start,&o.end_ns);if(reason)goto failed;
47:  reason=nh_memory_evaluate(&r->ledger,&first,&last,&zones,o.begin_ns,o.end_ns,stage,&o);
48:  r->observations[r->count++]=o;return reason;
49: failed:
50:  o.reason=(enum nh_memory_reason)reason;o.end_ns=r->now(r->context);r->observations[r->count++]=o;return reason;

